    title: "Compute resources", monthlyCost: "Monthly cost", readyIn: "Ready in", atRisk: "At risk", export: "Export",
    search: "Search resources or IDs…", clearSearch: "Clear search", depth: "Depth", collapse: "Collapse", all: "All",
